SET timezone = 'UTC';

-- ============================================================================
-- DROP ALL OBJECTS - Clean slate for database
-- ============================================================================
-- GENERATED FILE — DO NOT EDIT. Rewritten by every `effortless build`.
-- Generated by rulebook-to-postgres tool
-- ============================================================================

DO $$ 
DECLARE r RECORD; v_count INTEGER := 0;
BEGIN
    RAISE NOTICE 'Dropping views...';
    FOR r IN (SELECT table_name FROM information_schema.views WHERE table_schema = 'public') LOOP
        EXECUTE 'DROP VIEW IF EXISTS ' || quote_ident(r.table_name) || ' CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % views', v_count; v_count := 0;
    
    RAISE NOTICE 'Dropping functions...';
    FOR r IN (SELECT DISTINCT p.proname as function_name, pg_get_function_identity_arguments(p.oid) as function_args
              FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid
              WHERE n.nspname = 'public' AND p.prokind = 'f') LOOP
        EXECUTE 'DROP FUNCTION IF EXISTS ' || quote_ident(r.function_name) || '(' || r.function_args || ') CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % functions', v_count; v_count := 0;
    
    RAISE NOTICE 'Dropping tables...';
    FOR r IN (SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE') LOOP
        EXECUTE 'DROP TABLE IF EXISTS ' || quote_ident(r.table_name) || ' CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % tables', v_count;
END $$;

-- ============================================================================
-- CREATE TABLES - Normalized data only (no calculated fields)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Users: Login identities for the demo (stub auth).
-- ----------------------------------------------------------------------------
CREATE TABLE users (
  user_id                             TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  role                                TEXT                ,                     -- trainer | client | admin
  display_name                        TEXT                
);
COMMENT ON TABLE users IS 'Login identities for the demo (stub auth).';
COMMENT ON COLUMN users.role IS 'trainer | client | admin';

-- ----------------------------------------------------------------------------
-- Trainers: Personal trainers who log sessions and bill clients.
-- ----------------------------------------------------------------------------
CREATE TABLE trainers (
  trainer_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  full_name                           TEXT                ,
  hourly_rate                         NUMERIC                                   -- Default $/hour charged to clients.
);
COMMENT ON TABLE trainers IS 'Personal trainers who log sessions and bill clients.';
COMMENT ON COLUMN trainers.hourly_rate IS 'Default $/hour charged to clients.';

-- ----------------------------------------------------------------------------
-- Clients: Trainer's clients.
-- ----------------------------------------------------------------------------
CREATE TABLE clients (
  client_id                           TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  email                               TEXT                ,
  full_name                           TEXT                ,
  trainer                             TEXT                
);
COMMENT ON TABLE clients IS 'Trainer''s clients.';

-- ----------------------------------------------------------------------------
-- Invoices: An invoice bundles one or more sessions billed to a client.
-- ----------------------------------------------------------------------------
CREATE TABLE invoices (
  invoice_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  client                              TEXT                ,
  issue_date                          TIMESTAMPTZ         ,
  due_date                            TIMESTAMPTZ         ,
  tax_rate                            NUMERIC             ,                     -- Decimal (e.g. 0.08 = 8%).
  discount_amount                     NUMERIC             ,
  paid_amount                         NUMERIC             
);
COMMENT ON TABLE invoices IS 'An invoice bundles one or more sessions billed to a client.';
COMMENT ON COLUMN invoices.tax_rate IS 'Decimal (e.g. 0.08 = 8%).';

-- ----------------------------------------------------------------------------
-- Sessions: A logged training session. The atomic line item that rolls up into an invoice.
-- ----------------------------------------------------------------------------
CREATE TABLE sessions (
  session_id                          TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  client                              TEXT                ,
  session_date                        TIMESTAMPTZ         ,
  duration_hours                      NUMERIC             ,
  rate_override                       NUMERIC             ,                     -- If > 0, overrides the trainer's HourlyRate for this session.
  notes                               TEXT                ,
  invoice                             TEXT                
);
COMMENT ON TABLE sessions IS 'A logged training session. The atomic line item that rolls up into an invoice.';
COMMENT ON COLUMN sessions.rate_override IS 'If > 0, overrides the trainer''s HourlyRate for this session.';

-- ============================================================================
-- FK INDEXES - Performance only, always applied
-- ============================================================================

-- Clients
CREATE INDEX IF NOT EXISTS idx_clients_trainer ON clients (trainer);

-- Invoices
CREATE INDEX IF NOT EXISTS idx_invoices_client ON invoices (client);

-- Sessions
CREATE INDEX IF NOT EXISTS idx_sessions_client ON sessions (client);
CREATE INDEX IF NOT EXISTS idx_sessions_invoice ON sessions (invoice);

